mapper.select:
select a.BankCode,a.ProposalNo,a.RCode,a.Descr,a.MakeDate,a.MakeTime
from
TransactionTrack a
where 1=1
and a.TransactionCode = 'CalculateTransaction'

    and a.TransNo = #{transNo}


    and a.BankCode = #{bankCode}


    and a.ProposalNo = #{proposalNo}

order by a.MakeDate desc,a.MakeTime desc
